  <script>
    const CHART_SPEC = {
      chartType: 'Sankey',
      title: 'Lead Qualification & Closing Funnel',
      rationale: 'Incoming leads split proportionally into 70% Qualified and 30% Drop-off, then 55% Won and 15% Lost.',
      initialState: 'incoming',
      states: [
        { id: 'incoming', label: '100% Incoming', summary: '100% of incoming leads enter qualification, splitting into 70% Qualified and 30% Drop-off.', x: 66, y: 120 },
        { id: 'qualified', label: '70% Qualified', summary: '70% of incoming leads qualify and advance to closing, splitting into 55% Won and 15% Lost.', x: 210, y: 66 },
        { id: 'dropoff', label: '30% Drop-off', summary: '30% of incoming leads exit during initial qualification.', x: 210, y: 174 },
        { id: 'won', label: '55% Won', summary: '55% of incoming leads (out of 70% Qualified) close as Won.', x: 354, y: 66 },
        { id: 'lost', label: '15% Lost', summary: '15% of incoming leads (out of 70% Qualified) close as Lost.', x: 354, y: 174 }
      ],
      transitions: [
        { id: 't1', from: 'incoming', to: 'qualified', event: 'Qualify (70%)', guard: '70% share' },
        { id: 't2', from: 'incoming', to: 'dropoff', event: 'Drop-off (30%)', guard: '30% share' },
        { id: 't3', from: 'qualified', to: 'won', event: 'Win (55%)', guard: '55% share' },
        { id: 't4', from: 'qualified', to: 'lost', event: 'Lose (15%)', guard: '15% share' },
        { id: 't5', from: 'dropoff', to: 'incoming', event: 'Restart', guard: 'replay funnel' },
        { id: 't6', from: 'won', to: 'incoming', event: 'Restart', guard: 'replay funnel' },
        { id: 't7', from: 'lost', to: 'incoming', event: 'Restart', guard: 'replay funnel' }
      ],
      rules: [
        { id: 'R1', from: 'incoming', event: 'Qualify (70%)', guard: '70% share', to: 'qualified', text: '70% of 100% Incoming leads pass qualification into Qualified.' },
        { id: 'R2', from: 'incoming', event: 'Drop-off (30%)', guard: '30% share', to: 'dropoff', text: '30% of 100% Incoming leads exit at Drop-off.' },
        { id: 'R3', from: 'qualified', event: 'Win (55%)', guard: '55% share', to: 'won', text: '55% of total leads (from 70% Qualified) convert to Won.' },
        { id: 'R4', from: 'qualified', event: 'Lose (15%)', guard: '15% share', to: 'lost', text: '15% of total leads (from 70% Qualified) close as Lost.' },
        { id: 'R5', from: 'dropoff', event: 'Restart', guard: 'replay funnel', to: 'incoming', text: 'Restart returns from Drop-off to 100% Incoming to inspect another path.' },
        { id: 'R6', from: 'won', event: 'Restart', guard: 'replay funnel', to: 'incoming', text: 'Restart returns from Won to 100% Incoming to inspect another path.' },
        { id: 'R7', from: 'lost', event: 'Restart', guard: 'replay funnel', to: 'incoming', text: 'Restart returns from Lost to 100% Incoming to inspect another path.' }
      ],
      demoSequence: [
        'Qualify (70%)',
        'Win (55%)',
        'Restart',
        'Qualify (70%)',
        'Lose (15%)',
        'Restart',
        'Drop-off (30%)',
        'Restart'
      ]
    };

    const PATH_RIBBONS = {
      incoming: ['incoming-qualified', 'incoming-dropoff'],
      qualified: ['incoming-qualified', 'qualified-won', 'qualified-lost'],
      dropoff: ['incoming-dropoff'],
      won: ['incoming-qualified', 'qualified-won'],
      lost: ['incoming-qualified', 'qualified-lost']
    };

    (() => {
      let current = CHART_SPEC.initialState;
      let lastRuleId = null;
      let playTimer = null;
      let demoIndex = 0;

      const playBtn = document.querySelector('[data-tc-play]');
      const stepBtn = document.querySelector('[data-tc-step]');
      const resetBtn = document.querySelector('[data-tc-reset]');
      const logicBtn = document.querySelector('[data-tc-logic]');
      const themeBtn = document.querySelector('[data-tc-theme]');
      const drawer = document.getElementById('tc-logic-drawer');
      const triggersEl = document.querySelector('[data-tc-triggers]');
      const rulesEl = document.querySelector('[data-tc-rules]');
      const stateLabelEl = document.querySelector('[data-tc-state-label]');
      const stepDescEl = document.querySelector('[data-tc-step-desc]');
      const logicSvg = document.getElementById('tc-logic-svg');

      function stateById(id) {
        return CHART_SPEC.states.find((s) => s.id === id) || CHART_SPEC.states[0];
      }

      function fireEvent(eventName) {
        const match = CHART_SPEC.transitions.find((t) => t.from === current && t.event === eventName);
        if (!match) return false;
        current = match.to;
        const rule = CHART_SPEC.rules.find((r) => r.from === match.from && r.event === match.event && r.to === match.to);
        lastRuleId = rule ? rule.id : null;
        render();
        return true;
      }

      function jumpToState(stateId) {
        const target = CHART_SPEC.states.find((s) => s.id === stateId);
        if (!target) return;
        const via = CHART_SPEC.transitions.find((t) => t.from === current && t.to === stateId)
          || CHART_SPEC.transitions.find((t) => t.to === stateId);
        current = stateId;
        lastRuleId = via
          ? (CHART_SPEC.rules.find((r) => r.from === via.from && r.to === via.to)?.id ?? null)
          : null;
        render();
      }

      function renderTriggers() {
        triggersEl.querySelectorAll('button').forEach((b) => b.remove());
        const available = CHART_SPEC.transitions.filter((t) => t.from === current);
        const events = [...new Set(CHART_SPEC.transitions.map((t) => t.event))];
        events.forEach((ev) => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'tc-btn';
          btn.textContent = ev;
          const validNow = available.some((t) => t.event === ev);
          btn.disabled = !validNow;
          btn.addEventListener('click', () => { stopPlay(); fireEvent(ev); });
          triggersEl.appendChild(btn);
        });
      }

      function renderStage() {
        document.querySelectorAll('[data-state-node]').forEach((node) => {
          const id = node.getAttribute('data-state-node');
          const active = id === current;
          node.setAttribute('data-active', String(active));
          node.setAttribute('aria-pressed', String(active));
        });
        const activeRibbons = PATH_RIBBONS[current] || [];
        document.querySelectorAll('[data-ribbon]').forEach((ribbon) => {
          const key = ribbon.getAttribute('data-ribbon');
          ribbon.setAttribute('data-active', String(activeRibbons.includes(key)));
        });
      }

      function renderRules() {
        rulesEl.innerHTML = '';
        CHART_SPEC.rules.forEach((r) => {
          const li = document.createElement('li');
          li.className = 'tc-rule';
          const active = r.id === lastRuleId || r.from === current;
          li.dataset.active = String(active);
          li.innerHTML = `<span class="tc-rule-id">${r.id}</span><strong>${r.from} &rarr; ${r.to}</strong> (${r.event} &middot; ${r.guard})<br><span style="color:var(--tc-muted)">${r.text}</span>`;
          rulesEl.appendChild(li);
        });
      }

      function renderLogicFlowchart() {
        const ns = 'http://www.w3.org/2000/svg';
        logicSvg.querySelectorAll('.tc-lf-dyn').forEach((n) => n.remove());
        const g = document.createElementNS(ns, 'g');
        g.setAttribute('class', 'tc-lf-dyn');

        CHART_SPEC.transitions.forEach((t) => {
          const a = stateById(t.from);
          const b = stateById(t.to);
          const active = t.from === current;
          const path = document.createElementNS(ns, 'path');
          const d = a.x <= b.x
            ? `M ${a.x} ${a.y} L ${b.x} ${b.y}`
            : `M ${a.x} ${a.y + 18} Q ${(a.x + b.x) / 2} 246 ${b.x} ${b.y + 18}`;
          path.setAttribute('d', d);
          path.setAttribute('fill', 'none');
          if (a.x > b.x) path.setAttribute('stroke-dasharray', '4 3');
          path.setAttribute('stroke', active ? 'var(--tc-accent)' : 'var(--tc-border-strong)');
          path.setAttribute('stroke-width', active ? '2.2' : '1.4');
          g.appendChild(path);
        });

        CHART_SPEC.states.forEach((s) => {
          const isActive = s.id === current;
          const rect = document.createElementNS(ns, 'rect');
          rect.setAttribute('x', String(s.x - 48));
          rect.setAttribute('y', String(s.y - 18));
          rect.setAttribute('width', '96');
          rect.setAttribute('height', '36');
          rect.setAttribute('rx', '8');
          rect.setAttribute('fill', isActive ? 'var(--tc-accent-soft)' : 'var(--tc-surface)');
          rect.setAttribute('stroke', isActive ? 'var(--tc-accent)' : 'var(--tc-border-strong)');
          rect.setAttribute('stroke-width', isActive ? '2.2' : '1.3');
          g.appendChild(rect);

          const txt = document.createElementNS(ns, 'text');
          txt.setAttribute('x', String(s.x));
          txt.setAttribute('y', String(s.y + 4));
          txt.setAttribute('text-anchor', 'middle');
          txt.setAttribute('font-size', '11');
          txt.setAttribute('font-weight', isActive ? '700' : '600');
          txt.setAttribute('fill', 'var(--tc-text)');
          txt.textContent = s.label;
          g.appendChild(txt);
        });

        logicSvg.appendChild(g);
      }

      function render() {
        const st = stateById(current);
        stateLabelEl.textContent = st.label;
        stepDescEl.textContent = st.summary;
        renderTriggers();
        renderStage();
        renderRules();
        renderLogicFlowchart();
      }

      function stopPlay() {
        if (playTimer) { clearInterval(playTimer); playTimer = null; }
        playBtn.setAttribute('aria-pressed', 'false');
        playBtn.textContent = 'Play';
      }

      function stepOnce() {
        const seq = CHART_SPEC.demoSequence;
        if (seq.length) {
          for (let tries = 0; tries < seq.length; tries++) {
            const ev = seq[(demoIndex + tries) % seq.length];
            if (fireEvent(ev)) { demoIndex = (demoIndex + tries + 1) % seq.length; return; }
          }
        }
        const first = CHART_SPEC.transitions.find((t) => t.from === current);
        if (first) fireEvent(first.event);
      }

      playBtn.addEventListener('click', () => {
        if (playTimer) { stopPlay(); return; }
        playBtn.setAttribute('aria-pressed', 'true');
        playBtn.textContent = 'Pause';
        stepOnce();
        playTimer = setInterval(stepOnce, 1400);
      });

      stepBtn.addEventListener('click', () => { stopPlay(); stepOnce(); });
      resetBtn.addEventListener('click', () => {
        stopPlay();
        demoIndex = 0;
        current = CHART_SPEC.initialState;
        lastRuleId = null;
        render();
      });

      logicBtn.addEventListener('click', () => {
        const next = logicBtn.getAttribute('aria-expanded') !== 'true';
        logicBtn.setAttribute('aria-expanded', String(next));
        drawer.hidden = !next;
      });

      const darkQuery = window.matchMedia('(prefers-color-scheme: dark)');
      function currentTheme() {
        const explicit = document.documentElement.dataset.theme;
        if (explicit === 'dark' || explicit === 'light') return explicit;
        return darkQuery.matches ? 'dark' : 'light';
      }
      function syncTheme() {
        const isDark = currentTheme() === 'dark';
        themeBtn.setAttribute('aria-pressed', String(isDark));
        themeBtn.textContent = isDark ? 'Light mode' : 'Dark mode';
      }
      themeBtn.addEventListener('click', () => {
        document.documentElement.dataset.theme = currentTheme() === 'dark' ? 'light' : 'dark';
        syncTheme();
      });
      syncTheme();

      document.querySelectorAll('[data-state-node]').forEach((node) => {
        const id = node.getAttribute('data-state-node');
        node.addEventListener('click', () => { stopPlay(); jumpToState(id); });
        node.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault(); stopPlay(); jumpToState(id);
          }
        });
      });

      render();
    })();
  </script>
</body>
</html>
